package nthshaders.common;

import java.util.concurrent.atomic.AtomicBoolean;

import org.apache.logging.log4j.LogManager;

/**
 * Mod version and build commit (BuildInfo, generated by Gradle from gradle.properties and git), for the startup log and
 * the diagnostics. One copy per jar (nthshaders.common in Gadolinium, gambiarra.common in Gambiarra): the two only
 * differ in the package (the build checks this, task checkCommonCopies).
 */
public final class AddonVersion {

    private static final AtomicBoolean logged = new AtomicBoolean();

    private AddonVersion() {
    }

    /** "0.2.0 (commit abc1234)". */
    public static String describe() {
        return BuildInfo.VERSION + " (commit " + BuildInfo.COMMIT + ")";
    }

    /**
     * One line in the log, once per game: called from onLoad of each mixin plugin in the jar, and the first one to run logs it
     * (on the client and on a dedicated server).
     */
    public static void logOnce() {
        if (logged.compareAndSet(false, true)) {
            LogManager.getLogger(BuildInfo.MODID).info("[" + BuildInfo.MODID + "] " + BuildInfo.NAME + " {}, {}", describe(),
                    LaunchSide.isDedicatedServer() ? "dedicated server" : "client");
        }
    }

}
